// Short names for the types generated from contract/openapi.yaml.
// schema.d.ts is generated by `npm run contract:types` (or `npm run contract:sync`). Never edit it by hand.
import type { components, operations } from './schema';

type S = components['schemas'];

export type ApiErrorBody = S['Error'];
export type ApiErrorCode = S['Error']['code'];
export type Health = S['Health'];
export type Role = S['Role'];
export type User = S['User'];
export type SessionRequest = S['SessionRequest'];
export type Session = S['Session'];
export type Category = S['Category'];
export type EventStatus = S['EventStatus'];
export type OrganiserRef = S['OrganiserRef'];
export type EventCreate = S['EventCreate'];
export type EventUpdate = S['EventUpdate'];
// "FairEvent", not "Event", so it never clashes with the browser's built-in DOM Event type.
export type FairEvent = S['Event'];
export type EventPage = S['EventPage'];
export type EventSummary = S['EventSummary'];
export type SignupStatus = S['SignupStatus'];
export type Signup = S['Signup'];
export type SignupList = S['SignupList'];
export type NoticeKind = S['NoticeKind'];
export type Notice = S['Notice'];
export type NoticeList = S['NoticeList'];

// Query parameters, taken straight from the operations so they always match the yaml.
export type EventQuery = NonNullable<operations['listEvents']['parameters']['query']>;
export type MySignupsQuery = NonNullable<operations['listMySignups']['parameters']['query']>;
export type MySignupsScope = NonNullable<MySignupsQuery['scope']>;
